    "صفحةُ مختبرٍ خارجَ عزك. صورُ الصفحات: مصحفُ المدينة النبويّة برواية حفص عن عاصم، مجمّعُ الملك فهد لطباعة المصحف الشريف. نصُّ الآياتِ هو النصُّ المعتمَدُ في عزك. التفاسير من مجموعة «tafsir_api» المفتوحة، والترجمات من «quran-api»، والتلاوات من «EveryAyah».": "ইজিকের বাইরের একটি পরীক্ষাগার পৃষ্ঠা। পৃষ্ঠার ছবি: মদিনা মুসহাফ, আসেম থেকে হাফসের বর্ণনায়, বাদশাহ ফাহাদ পবিত্র কুরআন মুদ্রণ কমপ্লেক্স। আয়াতের লেখা সেই লেখা যার ওপর ইজিক নির্ভর করে। তাফসিরগুলো উন্মুক্ত সংগ্রহ «tafsir_api» থেকে, অনুবাদগুলো «quran-api» থেকে এবং তিলাওয়াতগুলো «EveryAyah» থেকে।",
